#include <vector>
#include <algorithm>

class Solution {
public:
    bool canTransform(std::vector<int>& nums, int k) {
        int pos = 0, neg = 0;
        for (int x : nums) {
            if (x == 1) pos++;
            else if (x == -1) neg++;
        }
        return std::min(pos, neg) <= k;
    }
};

class Solution {
    public boolean canTransform(int[] nums, int k) {
        int pos = 0, neg = 0;
        for (int x : nums) {
            if (x == 1) pos++;
            else if (x == -1) neg++;
        }
        return Math.min(pos, neg) <= k;
    }
}

/**
 * @param {number[]} nums
 * @param {number} k
 * @return {boolean}
 */
var canTransform = function(nums, k) {
    let pos = 0, neg = 0;
    for (const x of nums) {
        if (x === 1) pos++;
        else if (x === -1) neg++;
    }
    return Math.min(pos, neg) <= k;
};
